sparql:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?deputato_1 ?deputato_1_label ?incarico_2 ?gruppoParlamentare_4 ?gruppoParlamentare_4_label WHERE {
  ?deputato_1 rdf:type <http://dati.camera.it/ocd/deputato>;
    rdfs:label ?deputato_1_label;
    <http://dati.camera.it/ocd/rif_incarico> ?incarico_2.
  ?incarico_2 rdf:type <http://dati.camera.it/ocd/incarico>;
    <http://dati.camera.it/ocd/rif_gruppoParlamentare> ?gruppoParlamentare_4.
  ?gruppoParlamentare_4 rdfs:label ?gruppoParlamentare_4_label.
  VALUES ?gruppoParlamentare_4 {
    <http://dati.camera.it/ocd/gruppoParlamentare.rdf/gr4154>
  }
}
LIMIT 1000

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?atto_1 ?atto_1_label ?TextIniziativa_2 ?legislatura_4 ?legislatura_4_label WHERE {
  ?atto_1 rdf:type <http://dati.camera.it/ocd/atto>;
    rdfs:label ?atto_1_label;
    <http://dati.camera.it/ocd/iniziativa> ?TextIniziativa_2.
  VALUES ?TextIniziativa_2 {
    "Governo"
  }
  ?atto_1 <http://dati.camera.it/ocd/rif_leg> ?legislatura_4.
  ?legislatura_4 rdfs:label ?legislatura_4_label.
  VALUES ?legislatura_4 {
    <http://dati.camera.it/ocd/legislatura.rdf/costituente>
  }
}
LIMIT 1000

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?incarico_4 ?incarico_4_label WHERE {
  ?gruppoParlamentare_1 rdf:type <http://dati.camera.it/ocd/gruppoParlamentare>;
    <http://dati.camera.it/ocd/rif_incarico> ?incarico_4.
  ?incarico_4 rdf:type <http://dati.camera.it/ocd/incarico>;
    rdfs:label ?incarico_4_label;
    <http://dati.camera.it/ocd/ruolo> "PRESIDENTE";
    <http://dati.camera.it/ocd/rif_leg> <http://dati.camera.it/ocd/legislatura.rdf/repubblica_19>.
}
LIMIT 1000
